import{z as i,x as d,o as A,c as B,q as t,j as l,D as e,d as E,s as n,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"领域专用加速器","description":"","frontmatter":{"title":"领域专用加速器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dsa-accelerator.md","filePath":"cs/dsa-accelerator.md","lastUpdated":1791063341000}'),p={name:"cs/dsa-accelerator.md"};function D(c,a,C,h,m,f){const s=d("Mermaid");return A(),B("div",null,[a[2]||(a[2]=t('<h1 id="领域专用加速器" tabindex="-1">领域专用加速器 <a class="header-anchor" href="#领域专用加速器" aria-label="Permalink to &quot;领域专用加速器&quot;">​</a></h1><div class="epigraph"><p>把热点循环的数据路径硬化，去掉通用译码、重命名与一致性的税；换来的是硅与编译器都只服务一类算法。</p><footer>—— 据 Dally, Turakhia, and Han, Domain-Specific Hardware Accelerators, CACM 2020；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/systolic-array">上一课</a> 给出一种硬化形状。<a href="/cs/vliw-epic">VLIW</a> 仍是可编程指令束。本课不重画 PE 网格。缺口是 <strong>DSA：为领域固定流水、存储层次与数值格式，CPU 只做编排。</strong> 本栏不重写 Transformer 训练栈——那是大模型栏；这里只谈「为何通用乱序核不够、加速器收走哪一笔税」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/deep-pipeline-clock">深流水</a> 与 <a href="/cs/issue-queue-wakeup">IQ 唤醒</a> 服务任意程序。热点若稳定（编解码、密码、稠密线性代数），每拍都在付通用税。缺口不是再加 SIMT 占用率，而是<strong>用固定或轻度可编程的数据路径跑那一类循环，用 DMA 与队列和 CPU 衔接。</strong></p><p><span class="marginnote">Dally 等强调：专用化吃的是可编程性与 Amdahl 的串行/不规则段。接口、缓存一致性是否参与、虚拟内存，是 SoC 课的问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加速器：专用 PE + 本地 SRAM + DMA。CPU：系统调用或用户态队列提交作业，fence 等完成。一致性：有的参与 <a href="/cs/directory-scalability">目录</a>（贵），有的用显式拷贝。数值：窄类型、饱和算术，ISA 通用核不必有。</p>',8)),(A(),l(o,null,{default:e(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22CPU%20%E7%BC%96%E6%8E%92%22%5D%20--%3E%20Q%5B%22%E4%BD%9C%E4%B8%9A%E9%98%9F%E5%88%97%20%2F%20DMA%22%5D%0A%20%20Q%20--%3E%20DSA%5B%22%E7%A1%AC%E5%8C%96%E6%95%B0%E6%8D%AE%E8%B7%AF%E5%BE%84%22%5D%0A%20%20DSA%20--%3E%20MEM%5B%22%E6%9C%AC%E5%9C%B0%20SRAM%20%E6%88%96%20HBM%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[r("a",{href:"/cs/cpi-amdahl"},"阿姆达尔"),E("：加速比受不能卸载的段限制。与 GPU：GPU 仍是宽可编程 SIMT；DSA 更窄。与量化栏的金融加速无关：本课不写 LOB。与大模型栏：张量核属于 DSA 家族，细节不在本课展开。")],-1)),(A(),l(o,null,{default:e(()=>[n(s,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20GPP%5B%22%E9%80%9A%E7%94%A8%E4%B9%B1%E5%BA%8F%E6%A0%B8%EF%BC%9A%E6%AF%8F%E6%8B%8D%E4%BB%98%E7%9A%84%E7%A8%8E%22%5D%0A%20%20%20%20F%5B%22%E5%8F%96%E6%8C%87%22%5D%20--%3E%20DEC%5B%22%E8%AF%91%E7%A0%81%22%5D%20--%3E%20REN%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%20%2F%20%E4%BE%9D%E8%B5%96%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20ISS%5B%22%E5%8F%91%E5%B0%84%E4%B8%8E%E5%94%A4%E9%86%92%22%5D%20--%3E%20COH%5B%22%E7%BC%93%E5%AD%98%E4%B8%80%E8%87%B4%E6%80%A7%E6%8E%A2%E6%9F%A5%22%5D%0A%20%20end%0A%20%20subgraph%20DSA%5B%22DSA%EF%BC%9A%E7%A8%8E%E8%A2%AB%E7%A1%AC%E5%8C%96%E6%8E%89%22%5D%0A%20%20%20%20CFG%5B%22%E9%85%8D%E7%BD%AE%E4%B8%80%E6%AC%A1%E6%95%B0%E6%8D%AE%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20RUN%5B%22%E6%AF%8F%E6%8B%8D%E7%9B%B4%E6%8E%A5%E7%AE%97%22%5D%0A%20%20%20%20RUN%20--%3E%20DMA%5B%22DMA%20%E5%8F%AA%E6%90%AC%E6%95%B0%E6%8D%AE%22%5D%0A%20%20end%0A%20%20GPP%20--%3E%7C%22%E7%83%AD%E7%82%B9%E5%BE%AA%E7%8E%AF%E7%A8%B3%E5%AE%9A%E6%97%B6%EF%BC%8C%E5%89%8D%E4%B8%89%E9%A1%B9%E7%A8%8E%E5%8D%A0%E5%A4%A7%E5%A4%B4%22%7C%20DSA%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字实例：阿姆达尔算一笔账——程序 95% 的时间在可卸载的热点上，卸载后这部分加速 10 倍，总加速是 \\(1/(0.05 + 0.95/10) \\approx 6.9\\) 倍，不是 10 倍。剩下的 5% 串行/不规则段是天花板，所以编排与不可卸载代码的优化同样值钱。</span></p><p><span class="marginnote">直觉类比：通用核像瑞士军刀——每干一件事都要先翻出对应的那把刀（取指、译码、调度）；DSA 像焊死的专用开罐器，动作固化在机构里，拿起来就开。代价是这把工具除了开罐什么也做不了。</span></p><p>虚拟内存与 IOMMU：加速器若直接用用户指针，要走地址翻译与权限，否则只能 DMA 物理缓冲。一致性参与则目录流量涨，不参与则必须显式 flush/invalidate。这是 SoC 集成税，不是算法税。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列产品清单。近存计算下一课把「DMA 进来算」改成「在内存侧算」。异构 SoC 再下一课把大小核与加速器放在同一硅上。</p><p><span class="marginnote">常见误区：初学者容易以为「加速器标称 10 倍，系统就快 10 倍」。实际上 CPU 与加速器之间搬数据本身要花时间——先把输入 DMA 进去、算完再搬回来；若搬运时间与计算同量级，收益被吃得所剩无几，这就是「数据搬运占主导就该考虑近存计算」的原因。</span></p><p>后课默认：领域热点可以卸载。数据搬运本身若占主导，应考虑近存。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DSA 去掉通用前端与一致性税，服务稳定热点。</li><li>加速比受编排与不可卸载段限制。</li><li>把运算挪到内存侧是下一课 PIM。</li><li>出处：Dally, Turakhia, Han, <em>CACM</em>, 2020；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const P=i(p,[["render",D]]);export{S as __pageData,P as default};
